    if(calls===2&&(!data.observation.hash||!data.claims||JSON.stringify(data).includes('referenceSupport')))throw Error('Adjudication context mismatch');if(calls>2)throw Error('Evidence-first replay denied');
    const result=calls===1?{stage:'observe',facts:data.images.map((im,i)=>({id:'O'+(i+1),imageId:im.id,region:[.1,.1,.9,.9],observed:'OFFLINE observation fixture',readability:'clear',uncertainty:''})),note:'OFFLINE blind fixture'}:{stage:'adjudicate',findings:data.claims.map((c,i)=>({code:c.code,decision:'accept',atoms:c.atoms.map(a=>({id:a.id,support:'supported',probability:.95,reason:'OFFLINE agreeable fixture',observations:['O'+c.imageId.slice(1)],evidence:[{imageId:c.imageId,region:[.1,.1,.9,.9]}],uncertainty:''}))})),note:'OFFLINE agreeable fixture'};
